// A source expression may not silently retain an analytical review after its
// formula, conditions or local symbol definitions change.
import fs from 'node:fs';import vm from 'node:vm';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const w={},ctx=vm.createContext({window:w});for(const m of fs.readFileSync('students/index.html','utf8').matchAll(/src="([^"?]+\.js)/g)){if(m[1]==='app.js')break;vm.runInContext(fs.readFileSync('students/'+m[1],'utf8'),ctx)}
function csv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}return rows}
const lines=csv(fs.readFileSync('docs/STUDENTS_EXPRESSION_REVIEW_2026-10-20.csv','utf8')),headers=lines.shift(),records=lines.map(row=>Object.fromEntries(headers.map((k,i)=>[k,row[i]]))),by=new Map(records.map(r=>[r.id,r])),basis=JSON.parse(fs.readFileSync('docs/STUDENTS_EXPRESSION_REVIEW_BASIS_2026-10-20.json','utf8'));assert.equal(by.size,1498);assert.equal(w.MT_STUDY.sourceEquationRegister.length,by.size);let open=0;
for(const r of w.MT_STUDY.sourceEquationRegister){const a=by.get(r.id);assert.ok(a,'Missing reviewed ID '+r.id);const hash=crypto.createHash('sha256').update(JSON.stringify({formula:r.formula,conditions:r.conditions,symbols:r.symbols})).digest('hex');assert.equal(a.expression_context_sha256,hash,'Stale review '+r.id);assert.equal(a.expression,r.formula);assert.equal(a.conditions,r.conditions);assert.equal(a.review_decision,r.analyticalReview.decision);assert.ok(basis[a.chapter]?.[a.printed_page]);assert.equal(a.numeric_evidence_status,r.numericStatus||'PENDING');if(a.review_decision==='OPEN_MODEL_OR_SOURCE_LIMIT'){assert.ok(a.individual_finding&&r.analyticalReview.finding);open++}}
assert.equal(open,w.MT_STUDY.expressionReview.openModels);assert.equal(open,10);console.log(JSON.stringify({status:'PASS',expressions:by.size,openModelLimits:open,scope:'Review completeness and context digests, not independent mathematical proof of every relationship.'}));
